639:     pub fn parse_lyrics_text(track_id: &str, content: &str) -> LyricRecord {
640:         let mut lines = Vec::new();
641:         let mut is_synced = false;
642: 
643:         for line in content.lines() {
644:             let trimmed = line.trim();
645:             // Check for [mm:ss.xx] or [mm:ss]
646:             if trimmed.starts_with('[') && trimmed.len() > 7 {
647:                 if let Some(bracket_end) = trimmed.find(']') {
648:                     let timestamp_str = &trimmed[1..bracket_end];
649:                     let text = trimmed[bracket_end + 1..].trim().to_string();
650:                     if let Some(seconds) = Self::parse_lrc_timestamp(timestamp_str) {
651:                         is_synced = true;
652:                         lines.push(LyricLineRecord {
653:                             time: seconds,
654:                             text,
655:                         });
656:                         continue;
657:                     }
658:                 }
659:             }
660:             if !trimmed.is_empty() {
661:                 lines.push(LyricLineRecord {
662:                     time: -1.0,
663:                     text: trimmed.to_string(),
664:                 });
665:             }
666:         }
667: 
668:         LyricRecord {
669:             track_id: track_id.to_string(),
670:             is_synced,
671:             lines,
672:             plain_text: content.to_string(),
673:         }
674:     }
675: 
676:     fn parse_lrc_timestamp(ts: &str) -> Option<f64> {
677:         let parts: Vec<&str> = ts.split(':').collect();
678:         if parts.len() == 2 {
679:             let minutes: f64 = parts[0].parse().ok()?;
680:             let seconds: f64 = parts[1].parse().ok()?;
681:             return Some(minutes * 60.0 + seconds);
682:         }
683:         None
684:     }
