    let data = fs::read(&path).map_err(|e| format!("Failed to read thumbnail: {}", e))?;

    let mime = if path.to_lowercase().ends_with(".png") {
        "image/png"
    } else if path.to_lowercase().ends_with(".jpg") || path.to_lowercase().ends_with(".jpeg") {
        "image/jpeg"
    } else if path.to_lowercase().ends_with(".webp") {
        "image/webp"
    } else {
        "image/jpeg"
    };

    let encoded = base64::encode(&data);
    Ok(format!("data:{};base64,{}", mime, encoded))
}

#[tauri::command]
pub fn show_widget(app_handle: tauri::AppHandle) -> Result<(), String> {
    // Check if widget window already exists
    if app_handle.get_webview_window("widget").is_some() {
        return Ok(());
    }

    let window = tauri::WebviewWindowBuilder::new(&app_handle, "widget", tauri::WebviewWindowUrl::App("/?widget=1".into()))
        .title("PixelSong Widget")
        .inner_size(320.0, 140.0)
        .always_on_top(true)
        .skip_taskbar(true)
        .decorations(false)
        .transparent(true)
        .resizable(false)
        .focused(false)
        .build()
        .map_err(|e| e.to_string())?;

    Ok(())
}

#[tauri::command]
pub fn hide_widget(app_handle: tauri::AppHandle) -> Result<(), String> {
    if let Some(window) = app_handle.get_webview_window("widget") {
        window.hide().map_err(|e| e.to_string())?;
    }
    Ok(())
}
