import React, { useState, useEffect } from 'react';
import { Disc3 } from 'lucide-react';
import { api } from '../../services/tauriBridge';

interface ArtworkProps {
  src?: string;
  alt?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  className?: string;
  glow?: boolean;
}

export const Artwork: React.FC<ArtworkProps> = ({
  src,
  alt = 'Album Artwork',
  size = 'md',
  className = '',
  glow = false,
}) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [resolved, setResolved] = useState(false);

  useEffect(() => {
    setResolved(false);
    setImageUrl(null);

    if (!src) return;

    // Already a usable URL (http, asset://, data:)
    if (src.startsWith('http') || src.startsWith('asset://') || src.startsWith('data:')) {
      setImageUrl(src);
      setResolved(true);
      return;
    }

    // Local file path — resolve via Tauri to a base64 data URL so it renders
    api.getThumbnailDataUrl(src).then((url) => {
      if (url) {
        setImageUrl(url);
      }
      setResolved(true);
    }).catch(() => {
      setResolved(true);
    });
  }, [src]);

  const sizeClasses = {
    sm: 'w-10 h-10 rounded',
    md: 'w-14 h-14 rounded-md',
    lg: 'w-24 h-24 rounded-lg',
    xl: 'w-56 h-56 rounded-xl',
    full: 'w-full h-full rounded-2xl',
  };

  const glowStyle = glow
    ? {
        boxShadow: '0 10px 40px -10px var(--color-primary)',
      }
    : {};

  if (imageUrl) {
    return (
      <div
        className={`relative overflow-hidden bg-surface flex-shrink-0 border border-border/50 ${sizeClasses[size]} ${className}`}
        style={glowStyle}
      >
        <img
          src={imageUrl}
          alt={alt}
          className="w-full h-full object-cover"
          onError={(e) => {
            // Fallback to placeholder if image load fails
            (e.target as HTMLElement).style.display = 'none';
          }}
        />
      </div>
    );
  }

  return (
    <div
      className={`relative overflow-hidden bg-gradient-to-br from-surface to-background-secondary border border-border/50 flex items-center justify-center flex-shrink-0 text-text-subtle ${sizeClasses[size]} ${className}`}
      style={glowStyle}
    >
      <Disc3 className="w-1/2 h-1/2 opacity-60 animate-[spin_12s_linear_infinite]" />
    </div>
  );
};

