import { create } from 'zustand';
import { persist, devtools } from 'zustand/middleware';
import {
  CustomGradient,
  GradientConfig,
  GradientPreset,
  GradientSource,
  GradientStop,
  GradientType,
  RandomGradientStyle,
} from '../types';

// ===== PRESET GRADIENTS =====

export const GRADIENT_PRESETS: GradientPreset[] = [
  {
    id: 'midnight-purple',
    name: 'Midnight Purple',
    type: 'linear',
    angle: 135,
    stops: [
      { id: 's1', color: '#0f0c29', position: 0 },
