};

import React, { useState } from 'react';
import { Sparkles, Shuffle, Dice } from 'lucide-react';
import { useGradientStore } from '../../stores/gradientStore';
import { RandomGradientStyle } from '../../stores/gradientStore';

interface GradientRandomControlsProps {
  onSelect: (gradient: ReturnType<typeof useGradientStore>['generateRandomGradient']) => void;
}

const RANDOM_STYLES: { id: RandomGradientStyle; label: string; icon: any }[] = [
  { id: 'dark-moody', label: 'Dark & Moody', icon: null },
  { id: 'vibrant-colorful', label: 'Vibrant & Colorful', icon: null },
  { id: 'pastel-soft', label: 'Pastel & Soft', icon: null },
  { id: 'neon-cyberpunk', label: 'Neon & Cyberpunk', icon: null },
  { id: 'minimal-elegant', label: 'Minimal & Elegant', icon: null },
  { id: 'completely-random', label: 'Completely Random', icon: null },
];

export const GradientRandomControls: React.FC<GradientRandomControlsProps> = ({
  onSelect,
}) => {
  const { randomStyle, setRandomStyle, generateRandomGradient } = useGradientStore();
  const [selectedStyle, setSelectedStyle] = useState<RandomGradientStyle>('completely-random');

  const handleGenerate = () => {
    const gradient = generateRandomGradient(selectedStyle);
    onSelect(gradient);
  };

  return (
    <div className="space-y-4">
      <div>
        <label className="text-xs font-semibold text-text-subtle uppercase tracking-wider block mb-2">
          Random Style
        </label>
        <div className="flex gap-2 overflow-x-auto">
          {RANDOM_STYLES.map((s) => (
            <button
              key={s.id}
              onClick={() => {
                setSelectedStyle(s.id);
                setRandomStyle(s.id);
              }}
              className={`px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-colors ${
                selectedStyle === s.id
                  ? 'bg-primary text-primary-text shadow'
                  : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
              }`}
            >
              {s.label}
            </button>
          ))}
        </div>
      </div>

      <button
        onClick={handleGenerate}
        className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-primary text-primary-text text-xs font-semibold shadow-lg hover:bg-primary-hover transition-transform active:scale-95"
      >
        <Dice className="w-4 h-4" />
        <span>Randomize Now</span>
      </button>

      <div className="p-3 rounded-xl bg-background border border-border/50 text-xs">
        <p className="text-text-muted mb-1">
          <Sparkles className="w-3 h-3 inline mr-1" />
          New gradient generates automatically when a different song starts.
        </p>
        <p className="text-text-subtle">
          2–4 harmonious colors generated locally, no internet required.
        </p>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Search, Filter, Star, StarFill, Check, ArrowUpDown, FontSizes } from 'lucide-react';
import { useFontStore } from '../../stores/fontStore';
import { FontOption, FontCategory } from '../../types';

interface FontSelectorProps {
  onClose: () => void;
}

const CATEGORY_LABELS: Record<FontCategory, string> = {
  'modern-premium': 'Modern & Premium',
  'geometric-futuristic': 'Geometric & Futuristic',
  'minimal-professional': 'Minimal & Professional',
  'elegant-editorial': 'Elegant & Editorial',
  monospace: 'Monospace',
};

export const FontSelector: React.FC<FontSelectorProps> = ({ onClose }) => {
  const {
    fontFamily,
    fontWeight,
    favoriteFontIds,
    toggleFavoriteFont,
    fontLibrary,
    loadFont,
    isFontLoaded,
    setFontFamily,
    setFontWeight,
    setGlobalSizeScale,
    setHeadingSizeScale,
    setUiTextSizeScale,
    setLetterSpacing,
    globalSizeScale,
    headingSizeScale,
    uiTextSizeScale,
    letterSpacing,
  } = useFontStore();

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<FontCategory | 'all'>('all');
  const [previewText, setPreviewText] = useState('PixelSong');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  const filteredFonts = useMemo(() => {
    return fontLibrary
      .filter((f) => {
        if (selectedCategory !== 'all' && f.category !== selectedCategory) return false;
        if (searchQuery && !f.name.toLowerCase().includes(searchQuery.toLowerCase())) return false;
        return true;
      })
      .sort((a, b) => {
        const cmp = a.name.localeCompare(b.name);
        return sortDirection === 'asc' ? cmp : -cmp;
      });
  }, [searchQuery, selectedCategory, sortDirection, fontLibrary]);

  const currentFont = fontLibrary.find((f) => f.fontFamily === fontFamily);

  return (
    <div
      className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="bg-surface border border-border rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto p-6 flex flex-col">
        <div className="flex items-center justify-between mb-6 flex-shrink-0">
          <div>
            <h3 className="text-lg font-bold text-text">Typography Studio</h3>
            <p className="text-xs text-text-muted mt-0.5">
              Customize the application font. Changes apply across the entire player.
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded hover:text-rose-400 hover:bg-surface-hover transition-colors"
          >
            <span className="w-5 h-5" />
          </button>
        </div>

        {/* Search & Filters */}
        <div className="flex gap-2 mb-6">
          <div className="relative flex-1">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-subtle" />
            <input
              type="text"
              placeholder="Search fonts..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-background border border-border rounded-lg pl-9 pr-4 py-2 text-text outline-none focus:border-primary"
            />
          </div>
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-3 py-2 rounded-lg text-xs font-semibold transition-colors ${
              selectedCategory === 'all'
                ? 'bg-primary text-primary-text'
                : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
            }`}
          >
            All
          </button>
          {['modern-premium', 'geometric-futuristic', 'minimal-professional', 'elegant-editorial', 'monospace'].map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat as FontCategory)}
              className={`px-3 py-2 rounded-lg text-xs font-semibold transition-colors whitespace-nowrap ${
                selectedCategory === cat
                  ? 'bg-primary text-primary-text'
                  : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
              }`}
            >
              {CATEGORY_LABELS[cat as FontCategory]}
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-4">
          {/* Font Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredFonts.map((font) => {
              const isSelected = font.fontFamily === fontFamily;
              const isFav = favoriteFontIds.includes(font.id);
              const isLoaded = isFontLoaded(font.id);

              return (
                <div
                  key={font.id}
                  onClick={() => {
                    loadFont(font.id);
                    setFontFamily(font.fontFamily);
                  }}
                  className={`group cursor-pointer p-3 rounded-xl border transition-all duration-200 ${
                    isSelected
                      ? 'border-primary bg-primary/5 shadow-sm'
                      : 'border-border/60 hover:border-primary/50 hover:bg-surface-hover'
                  }`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-xs font-semibold text-text truncate">{font.name}</span>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleFavoriteFont(font.id);
                      }}
                      className="p-1 transition-colors"
                    >
                      {isFav ? (
                        <StarFill className="w-4 h-4 text-amber-400 fill-amber-400" />
                      ) : (
                        <Star className="w-4 h-4 text-text-subtle" />
                      )}
                    </button>
                    {isSelected && (
                      <Check className="w-4 h-4 text-primary fill-primary" />
                    )}
                  </div>

                  {/* Preview */}
                  <div
                    className="h-20 rounded-lg border border-border overflow-hidden mb-2 relative"
                    style={{
                      fontFamily: font.fontFamily,
                      fontWeight: isLoaded ? '400' : '400',
                    }}
                  >
                    <div className="absolute inset-0 flex items-center justify-center p-2">
                      <p
                        className="text-sm font-medium text-text truncate"
                        style={{ fontFamily: font.fontFamily }}
                      >
                        {previewText}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center justify-between text-[10px]">
                    <span className="text-text-subtle capitalize">{CATEGORY_LABELS[font.category]}</span>
                    {!isLoaded && (
                      <span className="text-[10px] text-primary animate-pulse">Loading...</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Typography Controls */}
          <div className="mt-8 pt-6 border-t border-border/60 space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle uppercase tracking-wider">
                Font Weight
              </label>
              <div className="flex gap-2">
                {[400, 500, 600, 700].map((w) => (
                  <button
                    key={w}
                    onClick={() => setFontWeight(w)}
                    className={`px-2 py-1 rounded text-xs font-medium transition-colors ${
                      fontWeight === w
                        ? 'bg-primary text-primary-text'
                        : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
                    }`}
                  >
                    {w}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between text-xs mb-1">
                <span className="text-text-subtle">Global Size</span>
                <span className="text-text-muted font-mono">{globalSizeScale.toFixed(1)}x</span>
              </div>
              <input
                type="range"
                min={0.8}
                max={1.5}
                step={0.1}
                value={globalSizeScale}
                onChange={(e) => setGlobalSizeScale(parseFloat(e.target.value))}
                className="w-full accent-primary"
              />
            </div>

            <div className="space-y-2">
              <div className="flex justify-between text-xs mb-1">
                <span className="text-text-subtle">Heading Size</span>
                <span className="text-text-muted font-mono">{headingSizeScale.toFixed(1)}x</span>
              </div>
              <input
                type="range"
                min={0.8}
                max={1.5}
                step={0.1}
                value={headingSizeScale}
                onChange={(e) => setHeadingSizeScale(parseFloat(e.target.value))}
                className="w-full accent-primary"
              />
            </div>

            <div className="space-y-2">
              <div className="flex justify-between text-xs mb-1">
                <span className="text-text-subtle">UI Text Size</span>
                <span className="text-text-muted font-mono">{uiTextSizeScale.toFixed(1)}x</span>
              </div>
              <input
                type="range"
                min={0.8}
                max={1.5}
                step={0.1}
                value={uiTextSizeScale}
                onChange={(e) => setUiTextSizeScale(parseFloat(e.target.value))}
                className="w-full accent-primary"
              />
            </div>

            <div className="space-y-2">
              <div className="flex justify-between text-xs mb-1">
                <span className="text-text-subtle">Letter Spacing</span>
                <span className="text-text-muted font-mono">{letterSpacing.toFixed(2)}em</span>
              </div>
              <input
                type="range"
                min={-0.05}
                max={0.1}
                step={0.01}
                value={letterSpacing}
                onChange={(e) => setLetterSpacing(parseFloat(e.target.value))}
                className="w-full accent-primary"
              />
            </div>

            <div className="flex justify-end gap-2 pt-4 border-t border-border/60">
              <button
                onClick={onClose}
                className="px-4 py-2 rounded-lg text-xs font-semibold text-text-muted hover:text-text"
              >
                Cancel
              </button>
              <button
                className="px-4 py-2 rounded-lg bg-primary text-primary-text text-xs font-semibold shadow hover:bg-primary-hover transition-colors"
              >
                Apply Font
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Palette, Sparkles, Image, RotateCcw, Check } from 'lucide-react';
import { useGradientStore } from '../../stores/gradientStore';
import { GradientEditor } from './GradientEditor';
import { GradientPresetGallery } from './GradientPresetGallery';
import { GradientRandomControls } from './GradientRandomControls';
import { gradientToCss } from '../../stores/gradientStore';
import {
  GradientSource,
  RandomGradientStyle,
} from '../../types';

interface GradientSettingsProps {
  onClose?: () => void;
}

const SOURCE_LABELS: Record<GradientSource, string> = {
  custom: 'Custom Gradient',
  preset: 'Preset Gallery',
  random: 'Random Generator',
};

const SOURCE_ICONS: Record<GradientSource, any> = {
  custom: Palette,
  preset: Image,
  random: Sparkles,
};

export const GradientSettings: React.FC<GradientSettingsProps> = ({ onClose }) => {
  const {
    enabled,
    source,
    customGradientId,
    presetId,
    randomStyle,
    animationEnabled,
    animationSpeed,
    customGradients,
    presets,
    setEnabled,
    setSource,
    setCustomGradient,
    setPreset,
    setRandomStyle,
    setAnimation,
    setAnimationSpeed,
    addCustomGradient,
    generateRandomGradient,
    resetToDefault,
  } = useGradientStore();

  const [editorOpen, setEditorOpen] = useState(false);
  const [editingGradient, setEditingGradient] = useState<ReturnType<typeof useGradientStore>['customGradients'][number] | null>(null);

  const currentGradient = customGradients.find((g) => g.id === customGradientId);
  const currentPreset = presets.find((p) => p.id === presetId);

  const handleSourceChange = (src: GradientSource) => {
    setSource(src);
  };

  const handleApplyPreset = (preset: import('../../stores/gradientStore').GradientPreset) => {
    setPreset(preset.id);
    setSource('preset');
  };

  const handleApplyRandom = (gradient: ReturnType<typeof generateRandomGradient>) => {
    addCustomGradient({
      name: gradient.name,
      type: gradient.type,
      angle: gradient.angle,
      stops: gradient.stops,
      isDefault: false,
    });
    setSource('custom');
  };

  const handleNewCustom = () => {
    setEditingGradient(null);
    setEditorOpen(true);
  };

  const handleEditCustom = (grad: typeof editingGradient) => {
    setEditingGradient(grad);
    setEditorOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Palette className="w-4 h-4 text-primary" />
          <h3 className="font-bold text-sm text-text">Now Playing Background</h3>
        </div>
        <button
          onClick={() => setEnabled(!enabled)}
          className={`relative w-10 h-5 rounded-full transition-colors ${
            enabled ? 'bg-primary' : 'bg-surface'
          }`}
        >
          <span
            className={`absolute top-1 ${
              enabled ? 'right-1' : 'left-1'
            } w-3 h-3 rounded-full bg-white transition-transform ${
              enabled ? 'translate-x-4' : 'translate-x-0'
            }`}
          />
        </button>
      </div>

      <p className="text-[11px] text-text-subtle">
        Apply a beautiful gradient background to the Now Playing screen.
      </p>

      {/* Gradient Source Selector */}
      <div className="p-4 bg-surface border border-border rounded-xl space-y-3">
        <label className="text-xs font-semibold text-text-subtle uppercase tracking-wider block">
          Gradient Source
        </label>
        <div className="flex gap-2">
          {['custom', 'preset', 'random'] as GradientSource[]?.map((src) => {
            const Icon = SOURCE_ICONS[src];
            const isActive = source === src;
            return (
              <button
                key={src}
                onClick={() => handleSourceChange(src)}
                className={`flex-1 flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-semibold transition-colors ${
                  isActive
                    ? 'bg-primary/10 text-primary border border-primary/30'
                    : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover border border-transparent'
                }`}
              >
                <Icon className="w-3 h-3" />
                <span>{SOURCE_LABELS[src]}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Custom Gradient Section */}
      {source === 'custom' && (
        <div className="p-4 bg-surface border border-border rounded-xl space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <h4 className="text-xs font-bold text-text">Custom Gradients</h4>
              <p className="text-[10px] text-text-muted">
                Create and save your own gradients
              </p>
            </div>
            <button
              onClick={handleNewCustom}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-primary/10 hover:bg-primary/20 text-primary text-xs transition-colors"
            >
              <Plus className="w-3 h-3" /> New
            </button>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
            {customGradients.map((g) => {
              const isActive = customGradientId === g.id;
              const css = gradientToCss(g);
              return (
                <button
                  key={g.id}
                  onClick={() => setCustomGradient(g.id)}
                  className={`relative h-16 rounded-lg overflow-hidden border transition-all duration-200 ${
                    isActive
                      ? 'border-primary ring-2 ring-primary ring-offset-1 ring-offset-surface shadow-md'
                      : 'border-border/60 hover:border-primary/50 hover:shadow-sm'
                  }`}
                >
                  <div className="absolute inset-0" style={{ background: css }} />
                  <div className="absolute bottom-1 left-1 right-1 p-1">
                    <p className="text-[9px] font-bold text-text truncate">{g.name}</p>
                  </div>
                  {isActive && (
                    <div className="absolute top-1 right-1 bg-primary text-primary-text rounded p-0.5">
                      <Check className="w-2.5 h-2.5" />
                    </div>
                  )}
                  <div className="absolute top-1 left-1 bg-black/30 text-white rounded px-1 py-0.5">
                    <span className="text-[9px]">{g.type}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Preset Section */}
      {source === 'preset' && (
        <GradientPresetGallery onSelect={handleApplyPreset} />
      )}

      {/* Random Section */}
      {source === 'random' && (
        <GradientRandomControls onSelect={handleApplyRandom} />
      )}

      {/* Animation Controls */}
      <div className="p-4 bg-surface border border-border rounded-xl space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h4 className="text-xs font-bold text-text">Animation</h4>
            <p className="text-[10px] text-text-muted">
              Subtle gradient animation while music plays
            </p>
          </div>
          <button
            onClick={() => setAnimation(!animationEnabled)}
            className={`relative w-10 h-5 rounded-full transition-colors ${
              animationEnabled ? 'bg-primary' : 'bg-surface'
            }`}
          >
            <span
              className={`absolute top-1 ${
                animationEnabled ? 'right-1' : 'left-1'
              } w-3 h-3 rounded-full bg-white transition-transform ${
                animationEnabled ? 'translate-x-4' : 'translate-x-0'
              }`}
            />
          </button>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between text-xs mb-1">
            <span className="text-text-subtle">Speed</span>
            <span className="text-text-muted font-mono">{animationSpeed.toFixed(1)}x</span>
          </div>
          <input
            type="range"
            min={0.5}
            max={5}
            step={0.5}
            value={animationSpeed}
            onChange={(e) => setAnimationSpeed(parseFloat(e.target.value))}
            className="w-full accent-primary"
            disabled={!animationEnabled}
          />
        </div>
      </div>

      {/* Reset */}
      <button
        onClick={resetToDefault}
        className="text-xs text-rose-400 hover:text-rose-300 hover:underline"
      >
        <RotateCcw className="w-3 h-3 inline mr-1" />
        Reset to Default
      </button>
    </div>
  );
};

