import { create } from 'zustand';
import { persist, devtools } from 'zustand/middleware';
import {
  NPVisualizerConfig,
  NPVisualizerStyle,
  NPVisualizerPlacement,
  NPVisualizerColorMode,
} from '../types';

const DEFAULT_CONFIG: NPVisualizerConfig = {
  enabled: true,
  style: 'circular-spectrum',
  placement: 'behind',
  intensity: 1.0,
  sensitivity: 1.0,
  glowIntensity: 0.6,
  animationSpeed: 1.0,
  opacity: 0.7,
  colorMode: 'artwork',
  customColor: '#38bdf8',
  reducedMotion: false,
};

interface NPVisualizerState extends NPVisualizerConfig {
  // Actions
  setEnabled: (enabled: boolean) => void;
  setStyle: (style: NPVisualizerStyle) => void;
  setPlacement: (placement: NPVisualizerPlacement) => void;
  setIntensity: (intensity: number) => void;
  setSensitivity: (sensitivity: number) => void;
  setGlowIntensity: (glow: number) => void;
  setAnimationSpeed: (speed: number) => void;
  setOpacity: (opacity: number) => void;
  setColorMode: (mode: NPVisualizerColorMode) => void;
  setCustomColor: (color: string) => void;
  setReducedMotion: (reduced: boolean) => void;
  setConfig: (config: Partial<NPVisualizerConfig>) => void;
  resetToDefault: () => void;
}

export const useNPVisualizerStore = create<NPVisualizerState>()(
  devtools(
    persist(
      (set) => ({
        ...DEFAULT_CONFIG,

        setEnabled: (enabled) => set({ enabled }),
        setStyle: (style) => set({ style }),
        setPlacement: (placement) => set({ placement }),
        setIntensity: (intensity) =>
          set({ intensity: Math.max(0.1, Math.min(2.0, intensity)) }),
        setSensitivity: (sensitivity) =>
          set({ sensitivity: Math.max(0.1, Math.min(2.0, sensitivity)) }),
        setGlowIntensity: (glow) =>
          set({ glowIntensity: Math.max(0.0, Math.min(1.0, glow)) }),
        setAnimationSpeed: (speed) =>
          set({ animationSpeed: Math.max(0.5, Math.min(3.0, speed)) }),
        setOpacity: (opacity) =>
          set({ opacity: Math.max(0.1, Math.min(1.0, opacity)) }),
        setColorMode: (mode) => set({ colorMode: mode }),
        setCustomColor: (color) => set({ customColor: color }),
        setReducedMotion: (reduced) => set({ reducedMotion: reduced }),
        setConfig: (config) => set((state) => ({ ...state, ...config })),

        resetToDefault: () => set({ ...DEFAULT_CONFIG }),
      }),
      {
        name: 'pixelsong-np-visualizer-storage',
        partialize: (state) => ({
          enabled: state.enabled,
          style: state.style,
          placement: state.placement,
          intensity: state.intensity,
          sensitivity: state.sensitivity,
          glowIntensity: state.glowIntensity,
          animationSpeed: state.animationSpeed,
          opacity: state.opacity,
          colorMode: state.colorMode,
          customColor: state.customColor,
          reducedMotion: state.reducedMotion,
        }),
      }
    )
  )
);

// ===== STYLE LABELS =====

export const NP_VISUALIZER_STYLES: { id: NPVisualizerStyle; label: string; description: string }[] = [
  { id: 'circular-spectrum', label: 'Circular Spectrum', description: 'Frequency bars in a circular formation' },
  { id: 'circular-waveform', label: 'Circular Waveform', description: 'Smooth animated waveform rings' },
  { id: 'audio-rings', label: 'Audio Rings', description: 'Expanding and contracting glowing rings' },
  { id: 'particle-visualizer', label: 'Particle Visualizer', description: 'Audio-reactive particles' },
  { id: 'flowing-waves', label: 'Flowing Waves', description: 'Flowing audio-reactive waves' },
  { id: 'radial-spectrum', label: 'Radial Spectrum', description: 'Frequency bars extending outward' },
  { id: 'ambient-glow', label: 'Ambient Glow', description: 'Soft audio-reactive lighting' },
];

export const NP_VISUALIZER_PLACEMENTS: { id: NPVisualizerPlacement; label: string }[] = [
  { id: 'behind', label: 'Behind Artwork' },
  { id: 'around', label: 'Around Artwork' },
  { id: 'below', label: 'Below Artwork' },
];

export const NP_COLOR_MODES: { id: NPVisualizerColorMode; label: string }[] = [
  { id: 'artwork', label: 'Album Artwork Colors' },
  { id: 'gradient', label: 'Current Gradient Colors' },
  { id: 'custom', label: 'Custom Colors' },
];

import React, { useEffect, useRef } from 'react';
import { useNPVisualizerStore } from '../../stores/npVisualizerStore';
import { useGradientStore } from '../../stores/gradientStore';
import { usePlayerStore } from '../../stores/playerStore';
import { api } from '../../services/tauriBridge';
import type {
  NPVisualizerStyle,
  NPVisualizerPlacement,
  NPVisualizerColorMode,
} from '../../types';

interface NowPlayingVisualizerProps {
  artworkColors?: { primary: string; secondary: string };
  className?: string;
}

const STYLE_LABELS: Record<NPVisualizerStyle, string> = {
  'circular-spectrum': 'Circular Spectrum',
  'circular-waveform': 'Circular Waveform',
  'audio-rings': 'Audio Rings',
  'particle-visualizer': 'Particle Visualizer',
  'flowing-waves': 'Flowing Waves',
  'radial-spectrum': 'Radial Spectrum',
  'ambient-glow': 'Ambient Glow',
};

export const NowPlayingVisualizer: React.FC<NowPlayingVisualizerProps> = ({
  artworkColors,
  className = '',
}) => {
  const {
    enabled,
    style,
    placement,
    intensity,
    sensitivity,
    glowIntensity,
    animationSpeed,
    opacity,
    colorMode,
    customColor,
    reducedMotion,
  } = useNPVisualizerStore();
  const { currentGradient } = useGradientStore();
  const { isPlaying } = usePlayerStore();

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number | null>(null);
  const colorsRef = useRef<string[]>([]);
  const particlesRef = useRef<{ x: number; y: number; vx: number; vy: number; size: number; baseSize: number; life: number }[]>([]);

  // Resolve colors based on color mode
  const resolveColors = (): string[] => {
    if (colorMode === 'custom') return [customColor];
    if (colorMode === 'gradient' && currentGradient) {
      return currentGradient.stops.map((s) => s.color);
    }
    if (colorMode === 'artwork' && artworkColors) {
      return [artworkColors.primary, artworkColors.secondary];
    }
    // Fallback to current theme primary
    const root = document.documentElement;
    const primary = getComputedStyle(root).getPropertyValue('--color-primary').trim() || '#38bdf8';
    const accent = getComputedStyle(root).getPropertyValue('--color-accent').trim() || '#818cf8';
    return [primary, accent];
  };

  useEffect(() => {
    colorsRef.current = resolveColors();
  }, [colorMode, customColor, currentGradient, artworkColors]);

  // Initialize particles for particle style
  useEffect(() => {
    if (style === 'particle-visualizer') {
      const pCount = 60;
      particlesRef.current = Array.from({ length: pCount }, () => ({
        x: 0, y: 0, vx: (Math.random() - 0.5) * 0.5, vy: (Math.random() - 0.5) * 0.5,
        size: 1 + Math.random() * 3, baseSize: 1 + Math.random() * 3, life: Math.random(),
      }));
    }
  }, [style]);

  useEffect(() => {
    if (!enabled || reducedMotion) return;

    let lastFetchTime = 0;
    let isFetching = false;
    let currentAnalysis = {
      frequencies: new Array(64).fill(0),
      waveform: new Array(128).fill(0),
      bass_energy: 0,
      mid_energy: 0,
      treble_energy: 0,
    };

    const render = (timestamp: number) => {
      // Fetch analysis at ~30 FPS
      if (timestamp - lastFetchTime >= 32 && !isFetching && isPlaying) {
        lastFetchTime = timestamp;
        isFetching = true;
        api
          .getVisualizerAnalysis()
          .then((res) => {
            currentAnalysis = res;
            isFetching = false;
          })
          .catch(() => {
            isFetching = false;
          });
      }

      const canvas = canvasRef.current;
      if (!canvas) {
        animRef.current = requestAnimationFrame(render);
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        animRef.current = requestAnimationFrame(render);
        return;
      }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
      }

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      const colors = colorsRef.current;
      const freq = currentAnalysis.frequencies;
      const wave = currentAnalysis.waveform;
      const bass = currentAnalysis.bass_energy;
      const mid = currentAnalysis.mid_energy;
      const treble = currentAnalysis.treble_energy;
      const energy = (bass + mid + treble) / 3;

      // Helper to get color with alpha
      const getColor = (idx: number, alpha: number): string => {
        const c = colors[idx % colors.length];
        if (c.startsWith('#')) {
          const r = parseInt(c.slice(1, 3), 16);
          const g = parseInt(c.slice(3, 5), 16);
          const b = parseInt(c.slice(5, 7), 16);
          return `rgba(${r}, ${g}, ${b}, ${alpha})`;
        }
        if (c.startsWith('hsl') || c.startsWith('rgb')) {
          return c.replace(/[\d.]+\)$/, (match) => {
            const num = parseFloat(match);
            return `${Math.min(1, Math.max(0, num > 1 ? num / 100 : num))})`;
          });
        }
        return `rgba(56, 189, 248, ${alpha})`;
      };

      // ===== RENDER STYLES =====
      switch (style) {
        case 'circular-spectrum': {
          const count = Math.min(48, freq.length);
          const angleStep = (Math.PI * 2) / count;
          const maxRadius = Math.min(width, height) * 0.42;
          const baseRadius = Math.min(width, height) * 0.28 + bass * 20 * sensitivity;

          ctx.save();
          ctx.translate(centerX, centerY);

          for (let i = 0; i < count; i++) {
            const angle = i * angleStep;
            const val = Math.min(1.0, (freq[i % freq.length] || 0) * sensitivity * intensity);
            const barLen = Math.max(2, val * maxRadius * 0.35);

            const x1 = Math.cos(angle) * baseRadius;
            const y1 = Math.sin(angle) * baseRadius;
            const x2 = Math.cos(angle) * (baseRadius + barLen);
            const y2 = Math.sin(angle) * (baseRadius + barLen);

            const grad = ctx.createLinearGradient(x1, y1, x2, y2);
            grad.addColorStop(0, getColor(i, 0.3));
            grad.addColorStop(1, getColor(i, opacity));

            ctx.strokeStyle = grad;
            ctx.lineWidth = Math.max(2, (Math.PI * 2 * baseRadius) / count - 2);
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();
          }
          ctx.restore();
          break;
        }

        case 'circular-waveform': {
          const count = wave.length;
          const angleStep = (Math.PI * 2) / count;
          const radius = Math.min(width, height) * 0.30 + mid * 25 * sensitivity;

          ctx.save();
          ctx.translate(centerX, centerY);
          ctx.beginPath();
          ctx.strokeStyle = getColor(0, opacity);
          ctx.lineWidth = 2.5;

          for (let i = 0; i < count; i++) {
            const angle = i * angleStep;
            const r = radius + wave[i] * 30 * sensitivity * intensity;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
          }
          ctx.closePath();
          ctx.stroke();

          // Inner glow
          ctx.beginPath();
          for (let i = 0; i < count; i++) {
            const angle = i * angleStep;
            const r = radius * 0.6 + wave[i] * 15 * sensitivity;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
          }
          ctx.closePath();
          ctx.strokeStyle = getColor(0, opacity * 0.4);
          ctx.lineWidth = 1.5;
          ctx.stroke();
          ctx.restore();
          break;
        }

        case 'audio-rings': {
          const rings = [
            { energy: bass, colorIdx: 0, baseR: 60 },
            { energy: mid, colorIdx: 1, baseR: 90 },
            { energy: treble, colorIdx: 2, baseR: 120 },
          ];

          for (const ring of rings) {
            const dynamicR = ring.baseR + ring.energy * 40 * sensitivity * intensity;
            ctx.beginPath();
            ctx.arc(centerX, centerY, dynamicR, 0, Math.PI * 2);
            ctx.strokeStyle = getColor(ring.colorIdx, opacity * 0.6);
            ctx.lineWidth = 3 + ring.energy * 4;
            ctx.stroke();

            // Glow
            ctx.beginPath();
            ctx.arc(centerX, centerY, dynamicR + 5, 0, Math.PI * 2);
            ctx.strokeStyle = getColor(ring.colorIdx, glowIntensity * 0.3);
            ctx.lineWidth = 1;
            ctx.stroke();
          }
          break;
        }

        case 'particle-visualizer': {
          const speedMult = 1.0 + bass * 2 * sensitivity;
          const particles = particlesRef.current;

          particles.forEach((p) => {
            p.x += p.vx * speedMult * animationSpeed;
            p.y += p.vy * speedMult * animationSpeed;

            // Wrap around center area
            const dx = p.x - centerX;
            const dy = p.y - centerY;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const maxDist = Math.min(width, height) * 0.45;

            if (dist > maxDist) {
              p.x = centerX + (dx / dist) * maxDist * 0.3;
              p.y = centerY + (dy / dist) * maxDist * 0.3;
            }

            const currentSize = p.baseSize + bass * 6 * sensitivity * intensity;
            ctx.beginPath();
            ctx.arc(p.x, p.y, currentSize, 0, Math.PI * 2);
            ctx.fillStyle = getColor(Math.floor(p.life * colors.length), 0.7 * opacity);
            ctx.fill();

            p.life += 0.02 * animationSpeed;
            if (p.life > 1) p.life = 0;
          });
          break;
        }

        case 'flowing-waves': {
          const time = Date.now() * 0.001 * animationSpeed;
          const waveCount = 3;

          for (let w = 0; w < waveCount; w++) {
            ctx.beginPath();
            ctx.moveTo(0, height * 0.5);

            for (let x = 0; x <= width; x += 4) {
              const energyFactor = (bass * 0.4 + mid * 0.4 + treble * 0.2) * sensitivity * intensity;
              const y =
                height * 0.5 +
                Math.sin(x * 0.005 + time * (w + 1) + w) *
                  (15 + energyFactor * 30) *
                  (placement === 'below' ? 1 : 0.6) +
                Math.cos(x * 0.003 + time) * 8;
              ctx.lineTo(x, y);
            }

            ctx.lineTo(width, height * 0.5);
            ctx.lineTo(width, height);
            ctx.lineTo(0, height);
            ctx.closePath();

            const alpha = (0.15 + w * 0.08) * opacity * glowIntensity;
            ctx.fillStyle = getColor(w, alpha);
            ctx.fill();
          }
          break;
        }

        case 'radial-spectrum': {
          const count = Math.min(32, freq.length);
          const angleStep = (Math.PI * 2) / count;
          const maxRadius = Math.min(width, height) * 0.45;

          for (let i = 0; i < count; i++) {
            const angle = i * angleStep;
            const val = Math.min(1.0, (freq[i % freq.length] || 0) * sensitivity * intensity);
            const barLen = Math.max(1, val * maxRadius);

            const x1 = centerX + Math.cos(angle) * 20;
            const y1 = centerY + Math.sin(angle) * 20;
            const x2 = centerX + Math.cos(angle) * (20 + barLen);
            const y2 = centerY + Math.sin(angle) * (20 + barLen);

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.strokeStyle = getColor(i, opacity);
            ctx.lineWidth = Math.max(1.5, (Math.PI * 2 * 20) / count - 1);
            ctx.lineCap = 'round';
            ctx.stroke();
          }
          break;
        }

        case 'ambient-glow': {
          const pulse = 1.0 + bass * 0.4 * sensitivity * intensity;
          const grad = ctx.createRadialGradient(
            centerX, centerY, 20,
            centerX, centerY, Math.min(width, height) * 0.5 * pulse
          );
          grad.addColorStop(0, getColor(0, glowIntensity * 0.4 * pulse));
          grad.addColorStop(0.5, getColor(1, glowIntensity * 0.15));
          grad.addColorStop(1, 'transparent');

          ctx.fillStyle = grad;
          ctx.fillRect(0, 0, width, height);
          break;
        }
      }

      ctx.restore();

      if (enabled) {
        animRef.current = requestAnimationFrame(render);
      }
    };

    animRef.current = requestAnimationFrame(render);

    return () => {
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
  }, [
    enabled, style, placement, intensity, sensitivity, glowIntensity,
    animationSpeed, opacity, colorMode, customColor, reducedMotion, isPlaying,
  ]);

  // Determine canvas dimensions based on placement
  let canvasStyle: React.CSSProperties = {};
  if (placement === 'below') {
    canvasStyle = {
      width: '100%',
      height: '120px',
      marginTop: '1rem',
      ...(className ? {} : {}),
    };
  } else {
    canvasStyle = {
      position: 'absolute',
      inset: 0,
      pointerEvents: 'none',
    };
  }

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={canvasStyle}
    />
  );
};

import React, { useState } from 'react';
import { Sparkles, RotateCcw, Palette, Layers, Smartphone, Check, X } from 'lucide-react';
import { useNPVisualizerStore } from '../../stores/npVisualizerStore';
import { useGradientStore } from '../../stores/gradientStore';
import { NP_VISUALIZER_STYLES, NP_VISUALIZER_PLACEMENTS, NP_COLOR_MODES } from '../../stores/npVisualizerStore';
import type { NPVisualizerStyle, NPVisualizerPlacement, NPVisualizerColorMode } from '../../types';

interface NPVisualizerSettingsProps {
  onClose?: () => void;
}

export const NPVisualizerSettings: React.FC<NPVisualizerSettingsProps> = ({ onClose }) => {
  const {
    enabled,
    style,
    placement,
    intensity,
    sensitivity,
    glowIntensity,
    animationSpeed,
    opacity,
    colorMode,
    customColor,
    reducedMotion,
    setEnabled,
    setStyle,
    setPlacement,
    setIntensity,
    setSensitivity,
    setGlowIntensity,
    setAnimationSpeed,
    setOpacity,
    setColorMode,
    setCustomColor,
    setReducedMotion,
    resetToDefault,
  } = useNPVisualizerStore();
  const { currentGradient } = useGradientStore();

  const [editorOpen, setEditorOpen] = useState(false);

  const currentStyle = NP_VISUALIZER_STYLES.find((s) => s.id === style);
  const currentPlacement = NP_VISUALIZER_PLACEMENTS.find((p) => p.id === placement);
  const currentColorMode = NP_COLOR_MODES.find((c) => c.id === colorMode);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Sparkles className="w-4 h-4 text-primary" />
          <h3 className="font-bold text-sm text-text">Now Playing Visualizer</h3>
        </div>
        <button
          onClick={() => setEnabled(!enabled)}
          className={`relative w-10 h-5 rounded-full transition-colors ${
            enabled ? 'bg-primary' : 'bg-surface'
          }`}
        >
          <span
            className={`absolute top-1 ${
              enabled ? 'right-1' : 'left-1'
            } w-3 h-3 rounded-full bg-white transition-transform ${
              enabled ? 'translate-x-4' : 'translate-x-0'
            }`}
          />
        </button>
      </div>

      <p className="text-[11px] text-text-subtle">
        Audio-reactive visualizer behind the square album artwork in Now Playing.
      </p>

      {!enabled && (
        <div className="p-3 bg-surface/50 border border-border/50 rounded-lg text-xs text-text-muted">
          Enable the visualizer to see audio-reactive effects behind your album artwork.
        </div>
      )}

      {enabled && (
        <>
          {/* Style Selector */}
          <div className="p-4 bg-surface border border-border rounded-xl space-y-3">
            <div className="flex items-center justify-between">
              <Layers className="w-4 h-4 text-primary" />
              <h4 className="text-xs font-bold text-text">Visualizer Style</h4>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2">
              {NP_VISUALIZER_STYLES.map((s) => {
                const isActive = style === s.id;
                return (
                  <button
                    key={s.id}
                    onClick={() => setStyle(s.id)}
                    className={`p-2 rounded-lg text-xs transition-all ${
                      isActive
                        ? 'bg-primary/10 text-primary border border-primary/30 shadow-sm'
                        : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover border border-transparent'
                    }`}
                    title={s.description}
                  >
                    <span className="text-[10px] font-semibold block text-center mb-1">
                      {s.label.split(' ')[0]}
                    </span>
                    <span className="text-[9px] text-text-subtle block text-center">
                      {s.label.split(' ').slice(1).join(' ')}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Placement Mode */}
          <div className="p-4 bg-surface border border-border rounded-xl space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-xs font-bold text-text">Placement Mode</h4>
              <p className="text-[10px] text-text-muted">Default: Behind Artwork</p>
            </div>
            <div className="flex gap-2">
              {NP_VISUALIZER_PLACEMENTS.map((p) => {
                const isActive = placement === p.id;
                return (
                  <button
                    key={p.id}
                    onClick={() => setPlacement(p.id)}
                    className={`flex-1 px-3 py-2 rounded-lg text-xs font-semibold capitalize transition-colors ${
                      isActive
                        ? 'bg-primary text-primary-text'
                        : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
                    }`}
                  >
                    {p.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Color Mode */}
          <div className="p-4 bg-surface border border-border rounded-xl space-y-3">
            <div className="flex items-center justify-between">
              <Palette className="w-4 h-4 text-primary" />
              <h4 className="text-xs font-bold text-text">Color Mode</h4>
            </div>
            <div className="flex gap-2">
              {NP_COLOR_MODES.map((c) => {
                const isActive = colorMode === c.id;
                return (
                  <button
                    key={c.id}
                    onClick={() => setColorMode(c.id)}
                    className={`flex-1 px-3 py-2 rounded-lg text-xs font-semibold capitalize transition-colors ${
                      isActive
                        ? 'bg-primary/10 text-primary border border-primary/30'
                        : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover border border-transparent'
                    }`}
                  >
                    {c.label}
                  </button>
                );
              })}
            </div>

            {colorMode === 'custom' && (
              <div className="space-y-2">
                <label className="text-xs font-semibold text-text-subtle block mb-1">Custom Color</label>
                <input
                  type="color"
                  value={customColor}
                  onChange={(e) => setCustomColor(e.target.value)}
                  className="w-10 h-8 rounded-lg cursor-pointer border-0 bg-transparent"
                />
              </div>
            )}

            {colorMode === 'gradient' && currentGradient && (
              <div className="space-y-2">
                <p className="text-[10px] text-text-muted">
                  Using gradient: <span className="text-text font-medium">{currentGradient.name}</span>
                </p>
                <div className="h-2 rounded-full overflow-hidden border border-border/50">
                  {currentGradient.stops.map((s, i) => (
                    <div
                      key={i}
                      className="h-full"
                      style={{
                        width: `${s.position / 100 * 100}%`,
                        background: s.color,
                      }}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Controls */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block">Intensity</label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min={0.1}
                  max={2.0}
                  step={0.1}
                  value={intensity}
                  onChange={(e) => setIntensity(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1"
                />
                <span className="text-[10px] font-mono text-text-muted">{intensity.toFixed(1)}x</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block">Sensitivity</label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min={0.1}
                  max={2.0}
                  step={0.1}
                  value={sensitivity}
                  onChange={(e) => setSensitivity(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1"
                />
                <span className="text-[10px] font-mono text-text-muted">{sensitivity.toFixed(1)}x</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block">Glow</label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min={0}
                  max={1}
                  step={0.1}
                  value={glowIntensity}
                  onChange={(e) => setGlowIntensity(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1"
                />
                <span className="text-[10px] font-mono text-text-muted">{Math.round(glowIntensity * 100)}%</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block">Opacity</label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min={0.1}
                  max={1}
                  step={0.1}
                  value={opacity}
                  onChange={(e) => setOpacity(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1"
                />
                <span className="text-[10px] font-mono text-text-muted">{Math.round(opacity * 100)}%</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3 mt-2">
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block">Speed</label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min={0.5}
                  max={3}
                  step={0.1}
                  value={animationSpeed}
                  onChange={(e) => setAnimationSpeed(parseFloat(e.target.value))}
                  className="w-full accent-primary h-1"
                />
                <span className="text-[10px] font-mono text-text-muted">{animationSpeed.toFixed(1)}x</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-semibold text-text-subtle block flex items-center gap-1">
                <Check className="w-3 h-3" />
                Reduced Motion
              </label>
              <button
                onClick={() => setReducedMotion(!reducedMotion)}
                className={`w-full py-2 rounded-lg text-xs font-semibold transition-colors ${
                  reducedMotion
                    ? 'bg-primary text-primary-text'
                    : 'bg-surface text-text-muted hover:text-text hover:bg-surface-hover'
                }`}
              >
                {reducedMotion ? 'On' : 'Off'}
              </button>
            </div>
          </div>

          <button
            onClick={resetToDefault}
            className="text-xs text-rose-400 hover:text-rose-300 hover:underline"
          >
            <RotateCcw className="w-3 h-3 inline mr-1" />
            Reset to Default
          </button>
        </>
      )}
    </div>
  );
};

