// Sample dominant colors from an artwork image URL
function sampleArtworkColors(imageUrl: string): Promise<{ primary: string; secondary: string } | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        if (!ctx) { resolve(null); return; }
        ctx.drawImage(img, 0, 0, 64, 64);
        const data = ctx.getImageData(0, 0, 64, 64).data;

        // Sample center pixel as primary
        const cx = 32, cy = 32;
        const centerIdx = (cy * 64 + cx) * 4;
        const primary = `rgb(${data[centerIdx]}, ${data[centerIdx + 1]}, ${data[centerIdx + 2]})`;

        // Sample corner area as secondary (avoid edges)
        const sx = 16, sy = 16;
        const cornerIdx = (sy * 64 + sx) * 4;
        const secondary = `rgb(${data[cornerIdx]}, ${data[cornerIdx + 1]}, ${data[cornerIdx + 2]})`;

        resolve({ primary, secondary });
      } catch {
        resolve(null);
      }
    };
    img.onerror = () => resolve(null);
    img.src = imageUrl;
  });
}

